		if (capturedPredecessor === null) {
			if (
				closedEpoch !== 0 ||
				proposed.priorCheckpointKind !== "genesis" ||
				proposed.priorCheckpointDigest !== CREATOR_AUTHOR_SETTLEMENT_GENESIS_SENTINEL
