	const sequence = Object.getOwnPropertyDescriptor(value, "fenceSequence");
	const version = Object.getOwnPropertyDescriptor(value, "version");
40→	return (
		action !== undefined &&
		Object.hasOwn(action, "value") &&
		action.enumerable === true &&
